RED='\033[0;31m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
YELLOW='\033[1;33m'
NC='\033[0m'

declare -a FAILED_TESTS

# ============================================
# Global Headers (from 04-api-contract.yaml x-global-headers)
# Payment is store-scoped: x-tenant-id AND x-store-id are BOTH required.
# ============================================
TENANT_HEADER="x-tenant-id: test-tenant-001"
STORE_HEADER="x-store-id: test-store-001"

# ============================================
# Helper Functions
# ============================================

# Extract a top-level field from JSON (jq preferred, python3 fallback).
# NEVER use grep for ID/money extraction.
extract_field() {
    local json=$1
    local field=$2
    if command -v jq &>/dev/null; then
        echo "$json" | jq -r ".$field"
    else
        echo "$json" | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get('$field',''))"
    fi
}

# Capture BOTH status code AND response body in a single request.
# Sets global LAST_STATUS and LAST_BODY. Both required headers always sent.
capture_with_status() {
    local http_method=$1
    local url=$2
    local payload=$3
    local response

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" -H "$STORE_HEADER" -d "$payload")
    else
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H "$TENANT_HEADER" -H "$STORE_HEADER")
    fi

    LAST_STATUS=$(echo "$response" | tail -1)
    LAST_BODY=$(echo "$response" | sed '$d')
}

# Assert exact status code (no capture needed).
assert_status() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    capture_with_status "$http_method" "$url" "$payload"

    if [ "$LAST_STATUS" = "$expected_status" ]; then
        echo -e "  ${GREEN}PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC} (Expected: $expected_status, Got: $LAST_STATUS)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $LAST_STATUS")
        return 1
    fi
}

# Assert exact status AND capture body (single request — prevents double-POST).
assert_status_and_capture() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    capture_with_status "$http_method" "$url" "$payload"

    if [ "$LAST_STATUS" = "$expected_status" ]; then
        echo -e "  ${GREEN}PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC} (Expected: $expected_status, Got: $LAST_STATUS)"
        echo "  Got body: $(echo "$LAST_BODY" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $LAST_STATUS")
        return 1
    fi
}

# Assert a fixed-string pattern is present in the response body.
# Use this (NOT regex) for money values — grep -F avoids decimal-dot escaping.
assert_json_field() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local json_pattern=$7

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected pattern: $json_pattern"

    capture_with_status "$http_method" "$url" "$payload"

    if echo "$LAST_BODY" | grep -qF "$json_pattern"; then
        echo -e "  ${GREEN}PASSED${NC}"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC}"
        echo "  Expected pattern: $json_pattern"
        echo "  Got: $(echo "$LAST_BODY" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Pattern '$json_pattern' not found")
        return 1
    fi
}

# Assert a fixed-string pattern is present in the LAST captured body (no new request).
# Used to make a second assertion on the body of a preceding assert_status_and_capture.
assert_last_body_contains() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local json_pattern=$4

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected pattern (last body): $json_pattern"

    if echo "$LAST_BODY" | grep -qF "$json_pattern"; then
        echo -e "  ${GREEN}PASSED${NC}"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC}"
        echo "  Expected pattern: $json_pattern"
        echo "  Got: $(echo "$LAST_BODY" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Pattern '$json_pattern' not found in last body")
        return 1
    fi
}

# Assert money field via jq/python numeric comparison (Decimal precision — NOT regex).
# Usage: assert_money_field <num> <name> <rule> <method> <url> <payload> <field> <op> <expected>
#   op ∈ { eq, ne, gt, ge, lt, le }
assert_money_field() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local field=$7
    local op=$8
    local expected=$9

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Assert $field $op $expected (Decimal)"

    capture_with_status "$http_method" "$url" "$payload"
    local actual
    actual=$(extract_field "$LAST_BODY" "$field")

    local ok
    ok=$(python3 -c "
from decimal import Decimal
import sys
try:
    a = Decimal(str('$actual'))
    e = Decimal(str('$expected'))
except Exception:
    print('ERR'); sys.exit(0)
op = '$op'
res = {'eq': a==e,'ne': a!=e,'gt': a>e,'ge': a>=e,'lt': a<e,'le': a<=e}.get(op, False)
print('YES' if res else 'NO')
")

    if [ "$ok" = "YES" ]; then
        echo -e "  ${GREEN}PASSED${NC} ($field=$actual $op $expected)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC} ($field=$actual, expected $op $expected)"
        echo "  Got: $(echo "$LAST_BODY" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - $field=$actual not $op $expected")
        return 1
    fi
}

