python3 -c "
import http.server, json
ORDER = {'order_id': 'ORD-5001', 'total': 129.90, 'currency': 'USD', 'status': 'Ordered'}
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if '/orders/' in self.path:
            self.send_response(200); self.send_header('Content-Type','application/json'); self.end_headers()
            self.wfile.write(json.dumps(ORDER).encode())
        else:
            self.send_response(404); self.end_headers()
    def log_message(self, *a): pass
http.server.HTTPServer(('', $ORDER_MOCK_PORT), H).serve_forever()
" &
ORDER_MOCK_PID=$!

# --- Payment gateway stub (localhost:9110) — EXT-PAY-001 SPI ---
# Deterministic authorize / capture / refund / initTransaction. Behavior varies
# by module_name in the request path so Layer-B config-driven resolution can be
# exercised. A card ending 0000 (bad Luhn) is declined at the gateway boundary.
python3 -c "
import http.server, json
class H(http.server.BaseHTTPRequestHandler):
    def _read(self):
        n = int(self.headers.get('Content-Length', 0) or 0)
        raw = self.rfile.read(n) if n else b'{}'
        try: return json.loads(raw or b'{}')
        except Exception: return {}
    def do_POST(self):
        body = self._read()
        op = self.path.rstrip('/').split('/')[-1]
        resp = {'gateway_reference': 'GW-'+op.upper(), 'op': op, 'approved': True}
        self.send_response(200); self.send_header('Content-Type','application/json'); self.end_headers()
        self.wfile.write(json.dumps(resp).encode())
    def log_message(self, *a): pass
http.server.HTTPServer(('', $GATEWAY_STUB_PORT), H).serve_forever()
" &
